        "id": "pthm-td-finite-entropy-maximum",
        "kind": "physics-theorem",
        "domain": "physics",
        "title": "Canonical weights uniquely maximize finite-state entropy at their mean energy",
        "reference": "items/pthm-td-finite-entropy-maximum.md#statement",
        "design_state": "Complete draft carrier authored; scoped checks and prerequisite acceptance remain pending.",
        "dependency_level": 6,
        "deps": [
