        "id": "ex-tdmath-flat-face-nonunique-minimizer",
        "kind": "example",
        "domain": "mathematics",
        "title": "A flat exposed face with many Fenchel minimizers",
        "reference": "research/plan-thermodynamics-track.md#L337-L374",
        "design_state": "Draft carrier authored; scoped checks and independent review remain pending.",
        "dependency_level": 4,
        "deps": [
